  public void Demo(){Engine.Connected=true;Engine.Connection="演示数据";string[] titles={"分析剪枝训练与当前结果","整理班级名单","迁移 BioTISR 训练到 leo","检查全量验证结果"};string[] states={"active","completed","approval","active"};string[] messages={"正在核对 200 张测试图的指标，检查各剪枝比例的完整性。","名单已整理完成，缺失信息已单独标记。","迁移方案已准备好，等待你在 Codex 中确认。","正在比较 PSNR、SSIM 和 LPIPS，准备结果汇总。"};if(Environment.GetCommandLineArgs().Contains("--unread-demo")){states=new[]{"completed","completed","active","approval"};}if(Environment.GetCommandLineArgs().Contains("--alerts-demo")){states=new[]{"input","approval","reconnecting","failed"};}for(int i=0;i<4;i++){var c=new Card{Id="demo"+i,Host=i==1?"local":"remote-ssh-discovered:virgo",Title=titles[i],Status=states[i],Message=messages[i],Interaction=J.Now-i*150,Started=J.Now-300,LastSeen=J.Now};if(Environment.GetCommandLineArgs().Contains("--alerts-demo")&&i==3)c.LastError="Model capacity exhausted";if(Environment.GetCommandLineArgs().Contains("--unread-demo")&&i==0)c.Unread=true;Engine.Cards[c.Key]=c;}Engine.Usage.WeeklyRemaining=71;Engine.Usage.Count=3;Engine.Usage.ResetsAt=J.Now+86400*5;Engine.Usage.Updated=J.Now;Engine.Usage.Credits=new[]{new Credit{Title="Full reset",Expires=J.Now+86400*6},new Credit{Title="Full reset",Expires=J.Now+86400*20},new Credit{Title="Full reset",Expires=J.Now+86400*21}};}
