  bool Attention(Card c){return c.UnreadResult||c.QuestionPending||c.Stale||c.Status=="approval"||c.Status=="input"||c.Status=="reconnecting"||Capacity(c);}
  void HighlightCard(Button button,Card card){
   if(!Attention(card))return;bool red=Capacity(card);
   string fill=red?(Design.Dark?"#342124":"#FFF0F0"):(Design.Dark?"#302719":"#FFF4DE");
   string hover=red?(Design.Dark?"#41272C":"#FFE4E4"):(Design.Dark?"#3C301D":"#FFEBC2");
