  string State(Card c){if(c.QuestionPending)return "等待回答";if(c.Stale)return Engine.Connected?"等待同步":"正在重连";if(Capacity(c))return "模型容量不足";if(c.UnreadResult)return "完成 · 未查看";switch(c.Status){case "active":return "进行中";case "completed":return "已完成";case "approval":return "需要确认";case "input":return "等待回答";case "reconnecting":return "正在重连";case "failed":case "systemError":return "发生错误";case "idle":return "空闲";case "notLoaded":return "未加载";case "interrupted":return "已中断";default:return "未知状态";}}
  string StateColor(Card c){if(c.QuestionPending)return Design.Amber;if(Capacity(c))return Design.Dark?"#F29A9A":"#BA3434";if(c.Stale||c.Status=="reconnecting")return Design.Amber;if(c.Status=="active")return Design.Accent;if(c.Status=="completed")return Design.Green;if(c.Status=="approval"||c.Status=="input")return Design.Amber;if(c.Status=="failed"||c.Status=="systemError")return Design.Dark?"#F29A9A":"#BA3434";return Design.Muted;}
  void RenderCards(){if(cards==null)return;var shown=Card.Sort(Engine.Cards.Values,Config);var signature=J.Json(shown.Select(c=>new{c.Key,c.Title,c.Message,c.Status,c.Stale,c.LastError,c.Interaction,c.QuestionPending,c.MessageUnavailable,c.Unread}).ToArray())+"/"+ActualWidth+"/"+ActualHeight+"/"+Design.Dark+"/"+Engine.Connected+"/"+PreviewOpen+"/"+Portrait;if(signature==renderedCards){UpdateCardWidths();return;}renderedCards=signature;cards.Children.Clear();cards.ColumnDefinitions.Clear();cards.RowDefinitions.Clear();if(PreviewOpen){RenderRail(shown);return;}if(shown.Length==0){var empty=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};empty.Children.Add(Design.Text(Engine.Connected?"这里将显示你的任务":"等待 Codex 连接",20));var hint=Design.Text(Engine.Connected?"开始一个任务，或在设置中切换主机。":"保持 Codex 桌面应用开启，看板会自动重连。",12,Design.Muted);hint.Margin=new Thickness(0,10,0,0);empty.Children.Add(hint);cards.Children.Add(empty);return;}
   double available=cardScroll!=null&&cardScroll.ActualWidth>0?cardScroll.ActualWidth:Math.Max(320,UiWidth)-30;double cw=Math.Max(Math.Max(190,260*Math.Min(1,available/Math.Max(1,UiWidth-30))),(available-10*(shown.Length-1))/shown.Length);if(Portrait)cards.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<shown.Length;i++){var c=shown[i];if(Portrait){if(i>0)cards.RowDefinitions.Add(new RowDefinition{Height=new GridLength(10)});cards.RowDefinitions.Add(new RowDefinition{Height=new GridLength(140)});}else{if(i>0)cards.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(10)});cards.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(cw)});}var b=Design.Button(null);b.Background=Design.B(Design.Surface);b.BorderBrush=Design.B(Design.Line);b.Padding=new Thickness(16,8,16,8);b.Margin=new Thickness(0);b.HorizontalContentAlignment=HorizontalAlignment.Stretch;b.VerticalContentAlignment=VerticalAlignment.Stretch;
    HighlightCard(b,c);
    var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(28)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(20)});b.Content=grid;
    var meta=new DockPanel();var status=new StackPanel{Orientation=Orientation.Horizontal};status.Children.Add(new System.Windows.Shapes.Ellipse{Width=5,Height=5,Fill=Design.B(StateColor(c)),Margin=new Thickness(0,0,6,0),VerticalAlignment=VerticalAlignment.Center});var label=Design.Text(State(c),Attention(c)?15:11,StateColor(c));label.FontWeight=Attention(c)?FontWeights.SemiBold:FontWeights.Normal;status.Children.Add(label);FrameworkElement badge=status;if(Attention(c)){badge=new Border{Child=status,Padding=new Thickness(9,5,9,5),CornerRadius=new CornerRadius(6),Background=Design.B(c.UnreadResult&&!Capacity(c)?(Design.Dark?"#234535":"#D8EFDF"):Capacity(c)?(Design.Dark?"#3B2428":"#FDEBEC"):(Design.Dark?"#352D1F":"#FFF2D8")),VerticalAlignment=VerticalAlignment.Center};}DockPanel.SetDock(badge,Dock.Right);meta.Children.Add(badge);meta.Children.Add(Design.Text(c.HostLabel,10,Design.Muted));grid.Children.Add(meta);
    var title=Design.Text(c.Title.Replace("\n"," "),17);title.FontWeight=FontWeights.SemiBold;title.TextWrapping=TextWrapping.Wrap;title.LineHeight=23;title.MaxHeight=46;title.Margin=new Thickness(0,2,0,0);title.VerticalAlignment=VerticalAlignment.Top;Grid.SetRow(title,1);grid.Children.Add(title);
    string msg=c.Message;if(c.MessageUnavailable)msg=msg.Length>0?"消息暂不可读 · 上次内容：\n"+msg:"状态已同步，消息暂不可读";if(string.IsNullOrWhiteSpace(msg))msg=c.Status=="active"?"正在处理，等待下一条进展…":"暂无最新进展";msg=msg.Replace("**","").Replace("`","").Replace("\r","").Trim();var progress=Design.Text(msg,14,Design.Muted);progress.TextWrapping=TextWrapping.Wrap;progress.LineHeight=22;progress.VerticalAlignment=VerticalAlignment.Top;progress.Margin=new Thickness(0,6,0,0);var clipped=new Border{Child=progress,ClipToBounds=true};Grid.SetRow(clipped,2);grid.Children.Add(clipped);AttachPreview(b,c);
    var bottom=new DockPanel{VerticalAlignment=VerticalAlignment.Bottom};var arrow=Design.Icon("arrow");DockPanel.SetDock(arrow,Dock.Right);bottom.Children.Add(arrow);bottom.Children.Add(Design.Text(c.Interaction>0?Local(c.Interaction).ToString("HH:mm")+"  最近交互":"最近任务",10,Design.Muted));Grid.SetRow(bottom,3);grid.Children.Add(bottom);
    System.Windows.Automation.AutomationProperties.SetName(b,c.Title+"，"+State(c)+"，返回 Codex");b.Click+=async delegate{if(DemoMode)return;b.IsEnabled=false;try{await Engine.Open(c);}catch{connection.Text="跳转失败，请确认 Codex 仍在运行";}finally{b.IsEnabled=true;}};if(Portrait)Grid.SetRow(b,i*2);else Grid.SetColumn(b,i*2);cards.Children.Add(b);
