  public static DateTime Local(double time){try{return new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddSeconds(time).ToLocalTime();}catch{return DateTime.MinValue;}}
  public void ShowUsage(){WakeSleep();if(activePanel is UsageWindow){ClosePanel();return;}settingsWindow=null;usageWindow=new UsageWindow(this);usageWindow.Show();if(!DemoMode){var t=Engine.RefreshUsage();}}
  public void ShowSettings(){WakeSleep();if(activePanel is SettingsWindow){ClosePanel();return;}usageWindow=null;settingsWindow=new SettingsWindow(this);settingsWindow.Show();}
  void UpdatePanelButtons(){UpdateDockButton();if(quota!=null){quota.Background=Design.B(activePanel is UsageWindow?Design.Hover:Design.Surface);quota.BorderBrush=Design.B(activePanel is UsageWindow?Design.Accent:Design.Line);}if(settingsButton!=null){settingsButton.Background=Design.B(activePanel is SettingsWindow?Design.Hover:Design.Canvas);settingsButton.BorderBrush=Design.B(activePanel is SettingsWindow?Design.Accent:Design.Canvas);}}
  public void Snapshot(string path){Design.Capture(this,path);}
  public void SnapshotUsage(string path){ShowUsage();ResizePanels();Design.Capture(this,path);}
  public void SnapshotSettings(string path){ShowSettings();if(Environment.GetCommandLineArgs().Contains("--expand-sleep-settings"))settingsWindow.ExpandSleepOptions();ResizePanels();Design.Capture(this,path);}
  public void SnapshotSettingsBottom(string path){if(!(activePanel is SettingsWindow))ShowSettings();ResizePanels();settingsWindow.ScrollBottom();Design.Capture(this,path);}
